import{_ as e,c as p,o as r,ah as t}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"爻位第十一","description":"杭氏易学 - 爻位第十一","frontmatter":{"title":"爻位第十一","description":"杭氏易学 - 爻位第十一"},"headers":[],"relativePath":"zh/classics/hangshi/012.md","filePath":"zh/classics/hangshi/012.md"}'),s={name:"zh/classics/hangshi/012.md"};function i(h,a,n,l,c,o){return r(),p("div",null,[...a[0]||(a[0]=[t('<h1 id="爻位第十一" tabindex="-1">爻位第十一 <a class="header-anchor" href="#爻位第十一" aria-label="Permalink to “爻位第十一”">​</a></h1><p>六位六虚</p><h3 id="六位" tabindex="-1">六位 <a class="header-anchor" href="#六位" aria-label="Permalink to “六位”">​</a></h3><p>分阴分阳，迭用柔刚，故《易》六位而成章。六位者，初爻二爻为地位，三爻四爻为人位，五爻上爻为天位。以乾卦例之，初九在地之下，故曰“潜”。九二地之上，故曰“田”。三爻为人之正位，故曰“君子”。四爻不当位，故曰“或”。五爻天位，故曰“在天”。上九在天之上，故曰“亢也”。</p><p>位有一定，而爻则变动无常。学者必先知有定之位，定其为阴为阳，为上为下，而后爻之奇偶当否，可得而言也 【偶居阴，奇居阳，为当，反之为不当】 。</p><p>分阴分阳，迭用柔刚。惟既济一卦，为阴阳柔刚各当其位，故曰“既济定也”。定则不动，不动则不生，而《易》道或几乎息矣。故荀虞均以乾坤成两既济为凶。《序卦》曰：“《易》不可穷也，故受之以未济终也。”此以阴阳之位言之也。若以用言，则一卦六爻，惟中四爻得用。初未用事，而上则失位。故《乾?上》曰：“高而无位”，《需?上》日“位不当也”。王弼曰“上下无位”者，指此也。</p><h3 id="六虚" tabindex="-1">六虚 <a class="header-anchor" href="#六虚" aria-label="Permalink to “六虚”">​</a></h3><p>《系传》曰：“上下无常，周流六虚。”六虚者，即初二三四五上之位也。爻实位虚，爻有上下，而位无变动。爻有柔刚，位有阴阳 【一三五为阳，二四六为阴】 ，刚柔杂居 【刚居阳，柔居阴，为当。或以刚居阴，柔居阳，则相杂而文生焉】 ，吉凶以著。《参同契》曰：“二用无爻位，周流行六虚。”二用者即九与六也。乾九坤六，上下升降，周流六虚，以成六十四卦。故观象者不可仅观所见之六爻。六爻之下，尚有六虚，皆与此所见之六爻相关。爻为飞，位为伏，实易辨而虚难知。必由实而究其虚，庶遇爻而知其用，于《易》之道思过半矣。</p><h3 id="八卦正位" tabindex="-1">八卦正位 <a class="header-anchor" href="#八卦正位" aria-label="Permalink to “八卦正位”">​</a></h3><p>爻位六而卦有八，八卦于六爻，各有其当位之爻，曰正位。家人曰“男正位乎外，女正位乎内”，言九五与六二，则但以阴阳言也。阴阳以二五爻为得中得正，乾坤为卦之宗主，亦阴阳之纯体。故乾以九五为正位，坤以六二为正位，坎离为乾坤之交 【坎中之阳即乾爻，离中之阴即坤爻】 。故坎离之正位，与乾坤同。震以初九为正位，艮以九三为正位，巽以六四为正位，兑以上六为正位。卦各有其正位，故六爻具六子之位。为图如下：</p><p>端木氏曰：天地六爻，坎离既济定位，五多功二多誉，位当也。离坎未济居方，三多凶四多惧，不当位也。有当位而不正者，而正位未有不当者也。而《彖》、《象》之言正则以二五，故八卦惟乾坤坎离之为得中得正也。</p><p>六爻三极定位，天地定位。六爻上山泽，下雷风，中水火。六爻三极，下二初地爻地极，雷风恒，天地下极立心恒，坤地极立不易方，二初震巽爻是也，五上天爻天极，山泽损天上极员 【损从员】 ，乾天恒无方，中日月斗，三人行，乾极与时偕行，五上艮兑爻是也。四三人爻人极，水火既济，天地中间人，于天地上下初终，首尾续终，中为人极。兼三才而两之，定上下中极，四三坎离爻是也。六爻三极，天地南北居方，六爻辨物辨等。乾坤六十四卦终下坎北极，故曰“初难知”，曰“亦不知极也”。此《易》居方上下六爻三极之道也。</p><p>右图与前图合观，则知爻位之隐见变化，不但卦有飞伏交互，而爻之飞伏交互，亦与卦等也。向之说《易》家，能究心于爻位之义者甚鲜，而于爻位之分，更未有言之者。来知德氏，虽有八卦之正位一图，而注中仍不能用，则以未明爻位之体用有别也。今合二图而一之，并附以说，庶阅者可了然矣。</p><p>六十四卦三百八十四爻，皆乾坤二用，周流六虚，至既济而全卦之爻位相当。故曰“既济定也”。</p><p>爻位既明，二用斯章。然乾元用九，纲领全《易》。地道无成，坤之用皆乾之用也。乾无方无体，乾之用皆见于坤之用也。孔子《文言传》曾发乾九用坤，坤六承乾之旨，已极详备。大明终始，六位时成，乃非既济而为未济，其故可深长思矣。</p><p>乾六位，火本天亲上。离五位，水本地亲下。坎二位，而上下刚柔应位。山泽，艮上位兑三位。雷风，震四位巽初位。而上下六位，巽伏，震起，兑见，艮止，皆中离坎日月象。故曰“大明终始六位时成 【下巽伏，上兑见，即坎象。下震起，上艮止，即离象。】 。”《上经》始乾坤终坎离，其往来卦十八。《下经》始咸恒终既未济，其往来卦十八。十八为二九数，乃离坎二卦日月终始。离一九，寅数止戌。坎一九，申数正辰。此离坎二九，皆乾用九圆，日月为大明象。乾二九十八卦，《上经》始乾坤，终坎离，大明终始六位是也。离坎二卦，南北终始，皆出入于震兑二卦，东西往来。震一九亥数止未，兑一九巳数止丑。此震一九离出震，兑一九坎出兑，皆乾用九圆。而上、下《经》各往来卦十八，始乾终既未济，乾六位成而坤天下平。此离坎上下六位，南北居方卦大明日月也。上下卦十八终始三十六，是为乾四九出入，南北上下为之极。其卦三十六，皆离坎首尾终之始之。而乾坤上下六十四卦六位，皆此离坎六位终始之。是乾用九乾圆象，而六十四卦以成终成始，乾大明终始，六位时成是也。</p><p>六爻二极，尤重在人。天地之气，以人而通。阴阳之道，以人而和。孔子赞《易》“立人之道”，以合乎天地之正。《京氏易传》：孔子曰“阳三阴四，位之正也”，三者东方之数，日之所出也。四者西方之数，日之所入也。言日月终天之道。故《易》卦六十四，分上下象阴阳也。故奇偶之数取之于乾坤。乾坤者，阴阳之根本也。阴阳之道备著于坎离。坎离者，阴阳之性命也，而其枢要皆在于三四两爻。于此求之，六十四卦之辞义可迎刃而解矣。图附后。</p><p>天地人六爻往复，天地上下，在人中爻三四回转。而上下天地爻，乃往复不穷。此乾坤六爻上下应位，二三四五同功异位，皆具此六爻往复中，皆在中人爻回转。人于天地上下，不见首尾，乃中间背脊，其道反复不已。天地往复，其道不穷。孔子六十四卦大象，著六十四“以”字。“以”，古文作 ，即结合上下两卦往复回转之象也。</p>',18)])])}const m=e(s,[["render",i]]);export{_ as __pageData,m as default};
